    CASE(OP_LOADL, BB) {
      switch (irep->pool[b].tt) {   /* number */
      case IREP_TT_INT32:
        VM_SET_INT_VALUE(regs[a], (mrb_int)irep->pool[b].u.i32);
        break;
      case IREP_TT_INT64:
#if defined(MRB_INT64)
        VM_SET_INT_VALUE(regs[a], (mrb_int)irep->pool[b].u.i64);
        break;
#else
#if defined(MRB_64BIT)
