CASE(OP_JMP, S) {
  ci->pc += (int16_t)a;
  JUMP;
}
CASE(OP_JMPIF, BS) {
  if (mrb_test(regs[a])) {
    ci->pc += (int16_t)b;
    JUMP;
  }
  NEXT;
}
CASE(OP_JMPNOT, BS) {
  if (!mrb_test(regs[a])) {
    ci->pc += (int16_t)b;
    JUMP;
  }
  NEXT;
}
CASE(OP_JMPNIL, BS) {
  if (mrb_nil_p(regs[a])) {
    ci->pc += (int16_t)b;
    JUMP;
  }
  NEXT;
}

CASE(OP_JMPUW, S) {
  a = (uint32_t)((ci->pc - irep->iseq) + (int16_t)a);
  CHECKPOINT_RESTORE(RBREAK_TAG_JUMP) {
    struct RBreak *brk = (struct RBreak*)mrb->exc;
    mrb_value target = mrb_break_value_get(brk);
    mrb_assert(mrb_integer_p(target));
    a = (uint32_t)mrb_integer(target);
    mrb_assert(a >= 0 && a < irep->ilen);
  }
  CHECKPOINT_MAIN(RBREAK_TAG_JUMP) {
    if (irep->clen > 0 &&
        (ch = catch_handler_find(irep, ci->pc, MRB_CATCH_FILTER_ENSURE))) {
      /* avoiding a jump from a catch handler into the same handler */
      if (a < mrb_irep_catch_handler_unpack(ch->begin) ||
          a > mrb_irep_catch_handler_unpack(ch->end)) {
        THROW_TAGGED_BREAK(mrb, RBREAK_TAG_JUMP, mrb->c->ci,
                           mrb_fixnum_value(a));
      }
    }
  }
