  int m2 = (b>>5)&0x1f;
  int kd = (b>>4)&0x1;
  int lv = (b>>0)&0xf;
  int offset = m1+r+m2+kd;
  mrb_value *stack;

  if (lv == 0) stack = regs + 1;
  else {
    struct REnv *e = uvenv(mrb, lv-1);
    if (!e || (!MRB_ENV_ONSTACK_P(e) && e->mid == 0) ||
        MRB_ENV_LEN(e) <= offset+1) {
      mrb_exc_set(mrb, mrb_exc_new_lit(mrb, E_LOCALJUMP_ERROR,
                                       "unexpected yield"));
      return VM_RAISE;
    }
    stack = e->stack + 1;
  }
  if (mrb_nil_p(stack[offset])) {
    mrb_exc_set(mrb, mrb_exc_new_lit(mrb, E_LOCALJUMP_ERROR,
                                     "unexpected yield"));
